{%- comment -%}
  Sale-day free gifts (Claude, Nov 21 2026), same approach as snippets/tme-lucky-gift. Only on the sale day (Eastern time):
  - Small Business Saturday, Nov 28 2026: 1 free handmade goodie with $35+ of our own books.
  - Cyber Monday, Nov 30 2026: 1 free mystery gift for every $50 spent.
  Outside its day a gift is taken back out of the cart. For testing, localStorage tmeSaleNow = a timestamp pretends it's that time. Thresholds use prices before discounts, like the Lucky Pack.
{%- endcomment -%}
{%- render 'tme-sale-gifts-calc' -%}
<script>
(function(){
  var G=[
    {id:55000797446462, k:'a', from:Date.UTC(2026,10,28,5), to:Date.UTC(2026,10,29,5), want:function(s){ return s.book>=3500?1:0; }},
    {id:55000797511998, k:'b', from:Date.UTC(2026,10,30,5), to:Date.UTC(2026,11,1,5), want:function(s){ return Math.min(20,Math.floor(s.spent/5000)); }}
  ];
  function clock(){ var t=Date.now(); try{ var o=Number(localStorage.getItem('tmeSaleNow')); if(o) t=o; }catch(e){} return t; }
  if(clock()>Date.UTC(2026,11,2)) return;
  var of=window.fetch; if(!of) return;
  var root=(window.Shopify&&Shopify.routes&&Shopify.routes.root)||'/';
  var busy=false, timer=null;
  function onCart(){ return /\/cart\/?$/.test(location.pathname); }
  function read(el){ return {book:Number(el.getAttribute('data-book'))||0, spent:Number(el.getAttribute('data-spent'))||0,
    a:{n:Number(el.getAttribute('data-a-qty'))||0, key:el.getAttribute('data-a-key')||''},
    b:{n:Number(el.getAttribute('data-b-qty'))||0, key:el.getAttribute('data-b-key')||''}}; }
  function post(url,body){ return of(root+url,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(body)}); }
  function done(){
    busy=false;
    if(onCart()){
      var c=0; try{ c=Number(sessionStorage.getItem('tmeSaleReload'))||0; sessionStorage.setItem('tmeSaleReload',String(c+1)); }catch(e){}
      if(c<3) location.reload();
    } else {
      document.dispatchEvent(new CustomEvent('tme:lucky-gift-changed'));
    }
  }
  function apply(s){
    var t=clock(), acts=[];
    G.forEach(function(g){
      var cur=s[g.k], want=(t>=g.from && t<g.to)?g.want(s):0;
      if(want===cur.n) return;
      if(cur.n===0) acts.push(function(){ return post('cart/add.js',{items:[{id:g.id,quantity:want}]}); });
      else if(cur.key) acts.push(function(){ return post('cart/change.js',{id:cur.key,quantity:want}); });
    });
    if(!acts.length){ try{ sessionStorage.removeItem('tmeSaleReload'); }catch(e){} return; }
    busy=true;
    acts.reduce(function(p,f){ return p.then(f); },Promise.resolve()).then(done,function(){ busy=false; });
  }
  function check(){
    if(busy) return;
    of(root+'?sections=tme-sale-gifts',{headers:{'Accept':'application/json'}})
      .then(function(r){ return r.json(); })
      .then(function(d){
        var h=d&&d['tme-sale-gifts']; if(!h) return;
        var t=document.createElement('div'); t.innerHTML=h;
        var el=t.querySelector('#tme-sale-gifts-data'); if(el) apply(read(el));
      })['catch'](function(){});
  }
  window.fetch=function(input){
    var p=of.apply(this,arguments);
    try{
      var u=typeof input==='string'?input:((input&&input.url)||'');
      if(!busy && /\/cart\/(add|change|update|clear)/.test(u)){
        p.then(function(){ clearTimeout(timer); timer=setTimeout(check,700); },function(){});
      }
    }catch(e){}
    return p;
  };
  var el=document.getElementById('tme-sale-gifts-data');
  if(el) apply(read(el));
})();
</script>
